CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT, test_price INTEGER NOT NULL DEFAULT 0, fes_price INTEGER NOT NULL DEFAULT 0, shoot_price INTEGER NOT NULL DEFAULT 0, thumbnail_url TEXT, status TEXT NOT NULL DEFAULT 'AVAILABLE', total_quantity INTEGER NOT NULL DEFAULT 1, note TEXT, location TEXT, is_combo INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS product_images (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, url TEXT NOT NULL, alt TEXT, kind TEXT NOT NULL DEFAULT 'gallery');
CREATE TABLE IF NOT EXISTS product_variants (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, name TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 0, attributes TEXT);
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, excerpt TEXT, content TEXT NOT NULL, cover_url TEXT, type TEXT NOT NULL DEFAULT 'ARTICLE', status TEXT NOT NULL DEFAULT 'DRAFT', seo_title TEXT, seo_description TEXT, published_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rentals (id TEXT PRIMARY KEY, customer_name TEXT NOT NULL, customer_phone TEXT, start_date TEXT NOT NULL, end_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'HOLD', deposit INTEGER NOT NULL DEFAULT 0, total_amount INTEGER NOT NULL DEFAULT 0, note TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rental_items (id TEXT PRIMARY KEY, rental_id TEXT NOT NULL REFERENCES rentals(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id), variant_id TEXT, quantity INTEGER NOT NULL DEFAULT 1, price INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS rentals_dates_idx ON rentals(start_date, end_date);
CREATE INDEX IF NOT EXISTS rental_items_product_idx ON rental_items(product_id);
